-- =============================================================================
-- 471 — LE CAHIER D'EXERCICES DE 6E (partie 5)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/6e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 471 --niveau 6e --fichiers technologie.n1 --suffixe 5 > supabase/contenu/471_exercices_6e_5.sql
--
-- 30 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   technologie.n1          30 exercices · 10 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('beb5b557-794c-5051-802f-05a3546b457e'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les objets du sac de Nora","competence":"analyser-document","situation":"Nora fait l’inventaire de son sac avant la rentrée. Pour chaque objet, elle a noté à quoi il sert.","documents":[{"id":"inv","type":"tableau","titre":"L’inventaire de Nora","colonnes":["Objet","Fonction d’usage"],"lignes":[["Gourde","Transporter de l’eau à boire"],["Casque audio","Écouter de la musique"],["Cartable","Transporter ses affaires"],["Lampe de poche","Éclairer dans le noir"]],"enteteLignes":true,"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche la case qui dit à quoi sert le casque audio.","aide":"Cherche la ligne « Casque audio », puis la colonne « Fonction d’usage ».","type":"zone","document":"inv","multiple":false},{"enonce":"Nora hésite entre deux sacs qui rendent le même service. Classe ces phrases : dit-on à quoi l’objet sert, ou pourquoi on préfère celui-là ?","aide":"La fonction d’usage répond à « à quoi ça sert ? ». La fonction d’estime dit ce qui fait préférer un objet à un autre.","type":"categories","categories":[{"id":"c0","texte":"Fonction d’usage"},{"id":"c1","texte":"Fonction d’estime"}],"items":[{"id":"i0","texte":"Éclairer un espace"},{"id":"i1","texte":"Transporter ses affaires"},{"id":"i2","texte":"Il est de ma marque préférée"},{"id":"i3","texte":"Sa forme me plaît beaucoup"},{"id":"i4","texte":"Se déplacer"}]},{"enonce":"Complète la règle de Nora.","aide":"Regarde les fonctions du tableau : Transporter, Écouter, Éclairer… Quelle sorte de mot est-ce ?","type":"trous","segments":["Une fonction d’usage s’écrit avec un ",0," à l’infinitif suivi d’un complément."],"banque":["prénom","verbe","nom","adjectif"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"La fonction d’usage du casque audio est **Écouter de la musique** : elle répond à la question « à quoi ça sert ? »."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c0"}},"explication":"Les **fonctions d’usage** (transporter, éclairer, se déplacer) expliquent pourquoi l’objet existe. Les **fonctions d’estime** (marque, forme) expliquent pourquoi on choisit celui-là."},{"cle":{"type":"trous","trous":[["verbe"]]},"affichage":"verbe","explication":"Elle commence par un **verbe à l’infinitif** : « Transporter de l’eau », « Éclairer dans le noir »."}]$ex$::jsonb),
  ('beb5b557-794c-5051-802f-05a3546b457e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un porte-gourde pour le club vélo","competence":"analyser-document","situation":"Le club vélo du collège veut fabriquer des porte-gourdes. Camille a recopié le cahier des charges sur une affiche.","documents":[{"id":"cdc","type":"fiche","modele":"affiche","entete":"Cahier des charges","sousTitre":"Porte-gourde du club vélo","emoji":"🚲","lignes":[{"texte":"Il coûte moins de 8 €","id":"z1"},{"texte":"Il pèse moins de 100 g","id":"z2"},{"texte":"Il se fixe avec deux vis","id":"z3"},{"texte":"Il ne présente aucune arête qui coupe","id":"z4"},{"texte":"Il peut être utilisé d’une seule main","id":"z5"}],"pied":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Une ligne de cette affiche n’a pas sa place dans un cahier des charges : elle dit COMMENT faire. Touche-la.","aide":"Un cahier des charges dit ce que l’objet doit faire, jamais comment le réaliser.","type":"zone","document":"cdc","multiple":false},{"enonce":"Range ces contraintes dans la bonne famille.","aide":"Un poids ou une taille se mesurent ; un prix s’achète ; la sécurité protège l’utilisateur.","type":"categories","categories":[{"id":"c0","texte":"Dimensions, poids"},{"id":"c1","texte":"Prix"},{"id":"c2","texte":"Sécurité"}],"items":[{"id":"i0","texte":"Moins de 100 g"},{"id":"i1","texte":"Aucune arête qui coupe"},{"id":"i2","texte":"Pas plus de 12 cm de large"},{"id":"i3","texte":"Moins de 8 €"}]},{"enonce":"Le club veut 12 porte-gourdes. Chacun doit coûter au plus 8 €. Quel est le budget maximal, en euros ?","aide":"Multiplie le prix maximal d’un porte-gourde par le nombre de porte-gourdes.","type":"nombre","unite":"€"},{"enonce":"Camille ajoute la ligne « Il peut être utilisé d’une seule main ». Qu’est-ce que cette ligne prend en compte ?","aide":"Qui va se servir du porte-gourde, et dans quelle situation ?","type":"choix","options":[{"id":"a","texte":"Le matériau choisi"},{"id":"b","texte":"L’utilisateur"},{"id":"c","texte":"Le prix de l’objet"},{"id":"d","texte":"La marque du fabricant"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"La ligne **« Il se fixe avec deux vis »** impose une solution technique. Le cahier des charges aurait dû dire seulement « Il se fixe solidement au cadre »."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c0","i3":"c1"}},"explication":"Le poids et la taille sont des **dimensions**, le montant est le **prix**, et l’absence d’arête qui coupe relève de la **sécurité**."},{"cle":{"type":"nombre","valeur":96,"tolerance":0},"affichage":"96 €","explication":"12 × 8 = **96 €** : c’est le budget maximal que le prix du cahier des charges permet."},{"cle":{"type":"choix","ids":["b"]},"explication":"Elle prend en compte **l’utilisateur** : un même besoin appelle des objets différents selon qui s’en sert."}]$ex$::jsonb),
  ('beb5b557-794c-5051-802f-05a3546b457e'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Trois cuillères pour un même besoin","competence":"raisonner","situation":"Au salon de la technologie, trois cuillères sont exposées. Elles servent toutes à manger, pourtant elles ne se ressemblent pas.","documents":[{"id":"tab","type":"tableau","titre":"Les trois cuillères","colonnes":["Cuillère","Pour qui ?","Particularité"],"lignes":[["A","Un adulte","Forme classique en métal"],["B","Un bébé","Bout souple, qui ne fait pas mal"],["C","Une personne qui n’a qu’une main valide","Manche épais et recourbé"]],"enteteLignes":true,"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Quelle est la fonction d’usage commune aux trois cuillères ?","aide":"Que fait-on, avec chacune de ces cuillères, au moment du repas ?","type":"choix","options":[{"id":"a","texte":"Décorer une table"},{"id":"b","texte":"Porter des aliments à la bouche"},{"id":"c","texte":"Remuer une soupe sur le feu"},{"id":"d","texte":"Mesurer un médicament"}],"multiple":false},{"enonce":"Touche la case qui explique pourquoi la cuillère du bébé ne le blesse pas.","aide":"Cherche la ligne du bébé, puis la colonne qui décrit la particularité.","type":"zone","document":"tab","multiple":false},{"enonce":"Associe chaque utilisateur à ce que la cuillère doit lui apporter.","aide":"Reprends la colonne « Particularité » du tableau.","type":"association","gauche":[{"id":"g0","texte":"Un adulte"},{"id":"g1","texte":"Un bébé"},{"id":"g2","texte":"Une personne avec une seule main valide"}],"droite":[{"id":"d0","texte":"Une prise facile à tenir"},{"id":"d1","texte":"Une taille et une forme habituelles"},{"id":"d2","texte":"Aucun risque de blessure"}]},{"enonce":"Range les étapes d’une démarche de conception dans le bon ordre.","aide":"Le besoin vient toujours avant l’objet, et le cahier des charges avant la solution.","type":"ordre","items":[{"id":"a","texte":"Écrire le cahier des charges"},{"id":"b","texte":"Choisir la solution technique"},{"id":"c","texte":"Repérer le besoin"},{"id":"d","texte":"Regarder qui va utiliser l’objet"}]},{"enonce":"Complète la conclusion.","aide":"Pense à la phrase du cours : « Un même besoin appelle des objets différents selon qui s’en sert ».","type":"trous","segments":["Les trois cuillères ont la même fonction d’",0,", mais pas la même solution technique, parce que les ",1," sont différents."],"banque":["prix","estime","usage","utilisateurs"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["b"]},"explication":"Les trois servent à **porter des aliments à la bouche** : c’est le même besoin, donc la même fonction d’usage."},{"cle":{"type":"zone","ids":["r1c2"]},"explication":"Son **bout souple** protège le bébé. C’est une contrainte de sécurité liée à l’utilisateur."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"Chaque utilisateur a ses contraintes : **adulte** (forme classique), **bébé** (bout souple), **une main valide** (manche épais et recourbé)."},{"cle":{"type":"ordre","ids":["c","d","a","b"]},"explication":"On part du **besoin**, on regarde **l’utilisateur**, on écrit le **cahier des charges**, puis on **choisit la solution**."},{"cle":{"type":"trous","trous":[["usage"],["utilisateurs"]]},"affichage":"usage · utilisateurs","explication":"Même fonction d’**usage**, mais des **utilisateurs** différents : chacun appelle sa propre solution."}]$ex$::jsonb),
  ('2d642a5c-891b-52bb-bcd8-ceca9ae91d98'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le vélo d’Inès, pièce par pièce","competence":"observer-schema","situation":"Inès regarde son vélo et se demande à quoi sert chaque pièce. Un vélo sert à se déplacer, mais il doit aussi remplir d’autres fonctions pour y arriver.","documents":[{"id":"velo","type":"schema","titre":"Un vélo vu de côté","largeur":340,"hauteur":215,"elements":[{"forme":"cercle","cx":80,"cy":150,"r":45,"motif":"aucun","id":"z1","zone":true},{"forme":"cercle","cx":270,"cy":150,"r":45,"motif":"aucun"},{"forme":"ligne","de":[80,105],"a":[80,195]},{"forme":"ligne","de":[35,150],"a":[125,150]},{"forme":"ligne","de":[270,105],"a":[270,195]},{"forme":"ligne","de":[225,150],"a":[315,150]},{"forme":"cercle","cx":270,"cy":150,"r":4,"motif":"plein"},{"forme":"polygone","points":[[80,142],[150,134],[150,166],[80,158]],"motif":"clair","id":"z2","zone":true},{"forme":"chemin","d":"M80 150 L125 95 L235 90 L150 150 Z M125 95 L150 150","motif":"aucun","id":"z3","zone":true},{"forme":"ligne","de":[235,90],"a":[270,150],"epaisseur":3,"id":"z4","zone":true},{"forme":"ligne","de":[235,90],"a":[231,68],"epaisseur":2},{"forme":"ligne","de":[231,68],"a":[255,63],"epaisseur":3,"id":"z5","zone":true},{"forme":"ligne","de":[252,64],"a":[258,78],"epaisseur":2,"id":"z6","zone":true},{"forme":"ligne","de":[258,78],"a":[251,105],"style":"pointilles"},{"forme":"rect","x":247,"y":103,"l":7,"h":11,"id":"z7","zone":true,"motif":"plein"},{"forme":"ligne","de":[125,95],"a":[125,86],"epaisseur":3},{"forme":"rect","x":104,"y":78,"l":42,"h":8,"arrondi":4,"id":"z8","zone":true,"motif":"plein"},{"forme":"cercle","cx":150,"cy":150,"r":16,"motif":"aucun","id":"z9","zone":true},{"forme":"ligne","de":[150,150],"a":[158,172],"epaisseur":3},{"forme":"rect","x":152,"y":171,"l":15,"h":5,"motif":"plein"}]}],"questions":[{"enonce":"Touche les deux pièces qui assurent la fonction technique « Diriger ».","aide":"Une pièce se tient avec les mains, l’autre porte la roue avant.","type":"zone","document":"velo","multiple":true},{"enonce":"Touche les trois pièces qui transmettent le mouvement des jambes jusqu’au sol.","aide":"Le mouvement part des pédales, passe par un anneau denté, puis par une liaison, et finit à la roue qui pousse le vélo.","type":"zone","document":"velo","multiple":true},{"enonce":"Complète.","aide":"La fonction d’usage dit à quoi l’objet sert. Les autres disent comment il y parvient.","type":"trous","segments":["Se déplacer est la fonction d’",0," du vélo. « Diriger » ou « Freiner » sont des fonctions ",1,"."],"banque":["usage","estime","décoratives","techniques"]}]}$ex$::jsonb,
